    for k in range(1,n+1):
        pts=comps[k]
        if pts==big: continue
        sr,sc=min(pts)
        tr,tc=sr-cy,sc-cx
        if 0<=tr and tr+pat.shape[0]<=H and 0<=tc and tc+pat.shape[1]<=W:
